-- =============================================================
-- Audit Reconciliation Control — seed ทะเบียนบัญชีจริง (38 บัญชี)
-- รันหลัง schema.sql :  Supabase → SQL Editor → วางไฟล์นี้ → Run
-- idempotent: รันซ้ำได้ ข้อมูลไม่ซ้ำ (on conflict do update)
-- company = บริษัทย่อย (subco) · provider ว่าง = บัญชีธนาคาร · source='bank'
-- =============================================================

on conflict (id) do update set
  account_raw  = excluded.account_raw,
  company      = excluded.company,
  bank         = excluded.bank,
  channel      = excluded.channel,
  provider     = excluded.provider,
  type         = excluded.type,
  holder       = excluded.holder,
  source       = excluded.source,
  file_pattern = excluded.file_pattern,
  active       = excluded.active,
  updated_at   = now();

-- เสร็จ: 38 บัญชี  |  ตรวจ:  select company, count(*) from accounts group by company order by 1;
